    def __init__(self, text):
        self.text = text
        self.pos = 0

    def peek(self):
        return self.text[self.pos] if self.pos < len(self.text) else None

    def parse_tree(self):
        """Parse '(' sequence-of-nodes variations ')' starting at self.pos."""
        if self.peek() != "(":
            raise ValueError("tree missing")
        self.pos += 1
        if self.peek() != ";":
            if self.peek() in (")", None):
                raise ValueError("tree with no nodes")
            raise ValueError("tree missing")
        nodes = []
        while self.peek() == ";":
            self.pos += 1
            nodes.append(SgfTree(self.parse_properties()))
        variations = []
        while self.peek() == "(":
            variations.append(self.parse_tree())
        if self.peek() != ")":
            raise ValueError("tree missing")
        self.pos += 1
        nodes[-1].children = variations
        for parent, child in zip(reversed(nodes[:-1]), reversed(nodes[1:])):
            parent.children = [child]
        return nodes[0]

    def parse_properties(self):
        properties = {}
        while True:
            char = self.peek()
            if char is None or char in ";()":
                return properties
            start = self.pos
            while self.peek() is not None and self.peek().isalpha():
                self.pos += 1
            key = self.text[start:self.pos]
            if not key:
                raise ValueError("properties without delimiter")
            if not key.isupper():
                raise ValueError("property must be in uppercase")
            if key in properties:
                raise ValueError(f"duplicate property: {key}")
            if self.peek() != "[":
                raise ValueError("properties without delimiter")
            values = []
            while self.peek() == "[":
                self.pos += 1
                values.append(self.parse_value())
            properties[key] = values

    def parse_value(self):
        result = []
        while True:
            char = self.peek()
            if char is None:
                raise ValueError("properties without delimiter")
            self.pos += 1
            if char == "]":
                return "".join(result)
            if char == "\\":
                escaped = self.peek()
                if escaped is None:
                    raise ValueError("properties without delimiter")
                self.pos += 1
                if escaped == "\n":
                    continue
                char = escaped
            if char != "\n" and char.isspace():
                char = " "
            result.append(char)


